D=Path(__file__).resolve().parent;R=D.parents[2];A=R/'art/creatures/tramino-family-v1';G=Path('C:/Users/user/.codex/generated_images/01a17924-9eaf-7951-8ded-c6920198ad3f')
specs=json.loads((D/'propostas.json').read_text(encoding='utf-8'));nodes=[];cards=[]
