 (p/'brief.md').write_text('# '+s['name']+' — '+s['age']+'\n\nDefinido: autor pediu uma linha completa candidata a parceiro emblemático, comparável em função a Agumon, Veemon ou Guilmon. Espécie, nomes, afinidade, papel de inicial e história são propostas; nenhum personagem existente é substituído.\n\nIdentidade: '+s['identity']+'\n\nHistória: '+s['story']+'\n\n45% criatura / 45% pipa viva / 10% acabamento 2D mangá. Continuidade seletiva por coral/índigo/marfim, testa dobrada, rabiola chevron e tensão nas articulações. Sem receitas ou habilidades numéricas definidas. Imagens externas não foram inputs de geração.',encoding='utf-8')
 (p/'revisao.md').write_text('# Conferência\n\n'+s['review']+'\n\nHá facetas e transições suaves residuais: ilustração de concept, não pixel art técnico. Fundo branco opaco intencional. Uma pose por forma, sem validação de animação, recortes ou rig. Em avaliação pelo autor, não integrado.',encoding='utf-8')
 with Image.open(p/'concept.png') as im:
  dimensions=list(im.size);mode=im.mode;thumb=ImageOps.contain(im.convert('RGB'),(850,590));x=k%2*900;y=k//2*700;sheet.paste(thumb,(x+(900-thumb.width)//2,y+65+(590-thumb.height)//2))
 draw.text((x+25,y+15),s['name']+' · '+s['age'],font=font,fill='#282443')
 (p/'manifest.json').write_text(json.dumps(dict(tool='image_gen.imagegen built-in',source=str(G/s['file']),sha256=hashlib.sha256((p/'concept.png').read_bytes()).hexdigest(),dimensions=dimensions,mode=mode,reference_role=('New design by written brief' if s['stage'] in [2,4] else 'Own Tramino pilot identity'),external_generation_inputs=False,decision_status='proposed',production_status='concept',implementation_status='not_integrated'),ensure_ascii=False,indent=2),encoding='utf-8')
 rel=lambda f:Path(os.path.relpath(p/f,D)).as_posix()
 n=dict(id=s['id'],name=s['name']+' (proposto)',age=s['age'],kind='stage',stage=s['stage'],identity=s['identity'],story=s['story'],decision_status='proposed',production_status='concept',art=rel('concept.png'),brief=rel('brief.md'));nodes.append(n)
 cards.append('<article><h2>'+escape(s['name'])+' · '+s['age']+'</h2><a href="'+n['art']+'"><img src="'+n['art']+'" alt="'+escape(s['identity'])+'"></a><p>'+escape(s['story'])+'</p><a href="'+n['brief']+'">Brief</a></article>')
